const $=id=>document.getElementById(id),money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n),pct=n=>n.toFixed(1)+'%';
const lessons=[
{name:'Compound growth',stage:'Foundations',title:'Small returns. A big difference.',intro:'Discover how earning returns on your returns changes the shape of growth.',chart:'Watch your money grow',simpleTitle:'Growth that builds on itself',simple:'Simple interest earns a return only on your starting amount. Compounding reinvests each year’s gains, so the next return is earned on a larger balance.',formula:'V = P × (1 + r)ᵗ',key:'P = starting amount · r = annual return · t = years',challenge:'Keep the return at 7% and move the time horizon from 10 to 30 years. Notice how the gap opens up.',inputs:[['p','Starting amount',1000,50000,1000,10000,'$'],['r','Annual return',0,15,.5,7,'%'],['t','Time horizon',1,40,1,20,'years']]},
{name:'Risk & return',stage:'Foundations',title:'Meet the shape of uncertainty.',intro:'An average return tells one part of the story. See how volatility fills in the rest.',chart:'A distribution of possible returns',simpleTitle:'Risk is a range of possibilities',simple:'Volatility describes how widely returns vary around their average. A wider curve means more uncertainty, including a greater chance of large gains and losses.',formula:'R ∼ Normal(μ, σ²)',key:'μ = expected return · σ = volatility · R = one-year return',challenge:'Hold the expected return at 7% and increase volatility. Watch the probability of a negative year rise.',inputs:[['mu','Expected return',-10,20,.5,7,'%'],['sigma','Volatility',1,40,1,15,'%']]},
{name:'Diversification',stage:'Intermediate',title:'Better together. Sometimes.',intro:'Mix two assets and discover why how they move together matters as much as their individual risk.',chart:'Finding the balance',simpleTitle:'Different movements can soften the ride',simple:'Correlation measures how two assets move together. Lower correlation can reduce the risk of a mix. Diversification helps with asset-specific risk, but it cannot eliminate every source of loss.',formula:'σₚ = √[w²σₐ² + (1−w)²σᵦ² + 2w(1−w)ρσₐσᵦ]',key:'w = share in A · ρ = correlation · σ = annual volatility',challenge:'Set the mix to 50 / 50, then slide correlation toward −1. The assets’ movements increasingly offset each other.',inputs:[['w','Weight in asset A',0,100,1,50,'%'],['rho','Correlation',-1,1,.1,.2,'']]},
{name:'Option payoffs',stage:'Advanced foundations',title:'A right. Not an obligation.',intro:'Explore a purchased call option: limited loss, with upside above the break-even price.',chart:'Your call option at expiration',simpleTitle:'Pay for the choice to buy later',simple:'A call gives its buyer the right to buy an asset at a fixed strike price. If the asset ends below that price, the call expires worthless. The premium is paid up front and can be lost in full.',formula:'Profit = max(S − K, 0) − premium',key:'S = asset price at expiration · K = strike price · per unit',challenge:'Raise the premium while keeping the strike fixed. Notice how the break-even price moves higher.',inputs:[['k','Strike price',50,150,5,100,'$'],['premium','Premium paid',1,30,1,10,'$'],['s','Price at expiration',0,200,5,120,'$']]}
];let active=0,state={};
function fmt(v,u){return u==='$'?money(v):u==='%'?v+'%':u==='years'?v+' years':Number(v).toFixed(1)}
function select(i){active=i;state=Object.fromEntries(lessons[i].inputs.map(x=>[x[0],x[5]]));render();}
function render(){const l=lessons[active];$('lessons').innerHTML=lessons.map((x,i)=>`<button class="${i===active?'active':''}" ${i===active?'aria-current="step"':''} data-lesson="${i}"><b>${i+1}</b><span>${x.name}<small>${x.stage}</small></span></button>`).join('');document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>select(+b.dataset.lesson));$('level').textContent=l.stage.toUpperCase();$('title').textContent=l.title;$('intro').textContent=l.intro;$('count').textContent=`EXPERIMENT 0${active+1} / 04`;$('chart-title').textContent=l.chart;$('simple-title').textContent=l.simpleTitle;$('simple').textContent=l.simple;$('formula').textContent=l.formula;$('formula-key').textContent=l.key;$('challenge').textContent=l.challenge;$('inputs').innerHTML=l.inputs.map(([id,label,min,max,step,d,u])=>`<div class="input"><div class="input-top"><label for="${id}">${label}</label><output class="value" id="value-${id}" for="${id}">${fmt(state[id],u)}</output></div><input type="range" id="${id}" min="${min}" max="${max}" step="${step}" value="${state[id]}"><div class="bounds"><span>${fmt(min,u)}</span><span>${fmt(max,u)}</span></div></div>`).join('');l.inputs.forEach(([id,,,,,u])=>$(id).oninput=e=>{state[id]=+e.target.value;$('value-'+id).textContent=fmt(state[id],u);update()});$('next').innerHTML=active===3?'Back to the basics <span>↺</span>':'Next concept <span>→</span>';update()}
function cdf(z){const t=1/(1+.2316419*Math.abs(z)),d=.3989422804*Math.exp(-z*z/2),p=1-d*t*(.31938153+t*(-.356563782+t*(1.781477937+t*(-1.821255978+t*1.330274429))));return z>=0?p:1-p}
function chart(series,xmin,xmax,ymin,ymax,xlabel,xformat,yformat,marker){const X=x=>62+(x-xmin)/(xmax-xmin)*670,Y=y=>260-(y-ymin)/(ymax-ymin)*225;let html='';for(let i=0;i<=4;i++){let y=ymin+(ymax-ymin)*i/4;html+=`<line x1="62" x2="732" y1="${Y(y)}" y2="${Y(y)}" stroke="#e9eeec" stroke-dasharray="3 5"/><text x="50" y="${Y(y)+4}" text-anchor="end">${yformat(y)}</text>`}for(let i=0;i<=4;i++){let x=xmin+(xmax-xmin)*i/4;html+=`<text x="${X(x)}" y="282" text-anchor="middle">${xformat(x)}</text>`}html+=`<text x="395" y="307" text-anchor="middle">${xlabel}</text>`;if(ymin<0&&ymax>0)html+=`<line x1="62" x2="732" y1="${Y(0)}" y2="${Y(0)}" stroke="#aebcba"/>`;series.forEach((s,i)=>{const d=s.data.map(([x,y],j)=>`${j?'L':'M'}${X(x).toFixed(2)},${Y(y).toFixed(2)}`).join(' ');if(s.fill)html+=`<path d="${d} L${X(s.data.at(-1)[0])},${Y(0)} L${X(s.data[0][0])},${Y(0)} Z" fill="${s.color}" opacity=".07"/>`;html+=`<path d="${d}" fill="none" stroke="${s.color}" stroke-width="3" ${s.dash?'stroke-dasharray="7 6"':''}/>`});if(marker)html+=`<line x1="${X(marker[0])}" x2="${X(marker[0])}" y1="35" y2="260" stroke="#abbfb4" stroke-dasharray="4 4"/><circle cx="${X(marker[0])}" cy="${Y(marker[1])}" r="6" fill="#1c8269" stroke="white" stroke-width="3"/>`;$('chart').innerHTML=html;$('legend').innerHTML=series.map(s=>`<span style="--c:${s.color}">${s.name}</span>`).join('')}
const samples=(a,b,f,n=100)=>Array.from({length:n+1},(_,i)=>{let x=a+(b-a)*i/n;return[x,f(x)]});
function stats(items){$('stats').innerHTML=items.map(([a,b])=>`<div class="stat"><label>${a}</label><strong>${b}</strong></div>`).join('')}
function update(){const s=state;let explanation='';if(active===0){let v=s.p*(1+s.r/100)**s.t,simple=s.p*(1+s.r/100*s.t);stats([['Future value',money(v)],['Total growth',money(v-s.p)]]);chart([{name:'Compound growth',color:'#20876d',fill:true,data:samples(0,s.t,t=>s.p*(1+s.r/100)**t)},{name:'Simple interest',color:'#a3b99e',dash:true,data:samples(0,s.t,t=>s.p*(1+s.r/100*t))}],0,s.t,0,v*1.12,'Years invested',x=>Math.round(x),y=>'$'+Math.round(y/1000)+'k');explanation=`After ${s.t} years, your ${money(s.p)} becomes ${money(v)}. Reinvesting returns adds ${money(v-simple)} more than simple interest. ${s.r===0?'At a 0% return, neither balance grows.':'The longer you give it, the more compounding can do.'} Assumes a constant annual return, with no deposits, fees, or taxes.`}
if(active===1){let prob=cdf(-s.mu/s.sigma)*100;stats([['Chance of a loss',pct(prob)],['Middle 68% of outcomes',`${Math.round(s.mu-s.sigma)}% to ${Math.round(s.mu+s.sigma)}%`]]);chart([{name:'One-year return density',color:'#20876d',fill:true,data:samples(-130,140,x=>Math.exp(-.5*((x-s.mu)/s.sigma)**2)/(s.sigma*Math.sqrt(2*Math.PI)),400)}],-130,140,0,1/(s.sigma*Math.sqrt(2*Math.PI))*1.15,'One-year return',x=>Math.round(x)+'%',y=>y.toFixed(2));explanation=`With ${s.mu}% expected return and ${s.sigma}% volatility, this model gives a ${pct(prob)} chance of a negative year. Higher volatility spreads outcomes farther apart. This normal-distribution illustration is not a forecast; real returns can have heavier tails, and the model can assign probability to impossible losses below −100%.`}
if(active===2){let w=s.w/100,risk=x=>Math.sqrt(Math.max(0,(x*20)**2+((1-x)*10)**2+2*x*(1-x)*s.rho*20*10)),v=risk(w),ret=w*9+(1-w)*4;stats([['Portfolio volatility',pct(v)],['Expected return',pct(ret)]]);chart([{name:'Portfolio risk',color:'#20876d',fill:true,data:samples(0,100,x=>risk(x/100))},{name:'Weighted individual risk',color:'#a3b99e',dash:true,data:samples(0,100,x=>10+x/10)}],0,100,0,23,'Allocation to asset A',x=>x+'%',y=>Math.round(y)+'%',[s.w,v]);explanation=`Your mix is ${s.w}% asset A and ${100-s.w}% asset B. At a correlation of ${s.rho.toFixed(1)}, volatility is ${pct(v)}, versus ${pct(w*20+(1-w)*10)} for the weighted individual risks. Assumed annual inputs: A returns 9% with 20% volatility; B returns 4% with 10% volatility. Correlations and returns can change.`}
if(active===3){let profit=x=>Math.max(x-s.k,0)-s.premium;stats([['Profit / loss per unit',money(profit(s.s))],['Break-even price',money(s.k+s.premium)]]);chart([{name:'Call buyer’s profit / loss',color:'#20876d',data:samples(0,200,profit)}],0,200,-35,155,'Asset price at expiration',x=>money(x),y=>money(y),[s.s,profit(s.s)]);explanation=`At an expiration price of ${money(s.s)}, your call has ${money(Math.max(s.s-s.k,0))} of intrinsic value. Subtract the ${money(s.premium)} premium and your ${profit(s.s)>=0?'profit is':'loss is'} ${money(Math.abs(profit(s.s)))} per unit. Your maximum loss is the premium; break-even is ${money(s.k+s.premium)}. Expiration payoff only, excluding fees and financing; this is not an option-pricing model.`}$('explanation').textContent=explanation}
$('reset').onclick=()=>select(active);$('next').onclick=()=>select((active+1)%lessons.length);select(0);
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'configure_quant_experiment',description:'Select a finance lesson and set its slider inputs, updating the visible chart and explanation.',inputSchema:{type:'object',properties:{lesson:{type:'integer',minimum:0,maximum:3},values:{type:'object',additionalProperties:{type:'number'}}},required:['lesson'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!Number.isInteger(input.lesson)||!lessons[input.lesson])throw Error('Invalid lesson');const values=input.values||{};for(const [key,v] of Object.entries(values)){const def=lessons[input.lesson].inputs.find(x=>x[0]===key);if(!def||!Number.isFinite(v)||v<def[2]||v>def[3])throw Error('Invalid input '+key)}select(input.lesson);Object.assign(state,values);render();return{lesson:lessons[active].name,inputs:{...state},explanation:$('explanation').textContent}}})).catch(()=>{})}catch{}}
